1	/* ============================================================
2	   MISSION HERO — mission-hero.module.css
3	   ============================================================ */
4	
5	.section {
6	  background-color: transparent;
7	  background-image: url('/images/webflow/hero-background-1.png'),
8	    linear-gradient(180deg, #019ae614 0%, #019ae600 100%);
9	  background-position: 50% 100%, 0 0;
10	  background-repeat: no-repeat, repeat;
11	  background-size: cover, auto;
12	  padding-top: 4rem;
13	  padding-bottom: 0;
14	}
15	
16	.container {
17	  max-width: 80rem;
18	  margin-left: auto;
19	  margin-right: auto;
20	  padding-left: 2rem;
21	  padding-right: 2rem;
22	}
23	
24	.inner {
25	  text-align: center;
26	  max-width: 70rem;
27	  margin-left: auto;
28	  margin-right: auto;
29	  padding-bottom: 3rem;
30	}
31	
32	/* ── Badge ── */
33	.badge {
34	  display: inline-flex;
35	  align-items: center;
36	  justify-content: center;
37	  background-color: rgba(33, 207, 255, 0.1);
38	  border: 1px solid rgba(33, 207, 255, 0.3);
39	  border-radius: 999px;
40	  padding: 6px 18px;
41	  margin-bottom: 1.5rem;
42	}
43	
44	.badgeText {
45	  background: linear-gradient(90deg, #21cfff, #019ae6);
46	  -webkit-background-clip: text;
47	  -webkit-text-fill-color: transparent;
48	  background-clip: text;
49	  font-family: 'Roobert PRO', Arial, sans-serif;
50	  font-size: 14px;
51	  font-weight: 600;
52	  line-height: 1.4;
53	  letter-spacing: 0.01em;
54	}
55	
56	/* ── Heading ── */
57	.heading {
58	  color: #092245;
59	  font-family: 'Roobert PRO', Arial, sans-serif;
60	  font-size: 48px;
61	  font-weight: 700;
62	  line-height: 1.2;
63	  margin-top: 0;
64	  margin-bottom: 1.25rem;
65	}
66	
67	/* ── Subtitle ── */
68	.subtitle {
69	  color: #2b2b2b;
70	  font-family: 'Roobert PRO', Arial, sans-serif;
71	  font-size: 16px;
72	  font-weight: 400;
73	  line-height: 28px;
74	  max-width: 52rem;
75	  margin-left: auto;
76	  margin-right: auto;
77	  margin-bottom: 2.5rem;
78	}
79	
80	/* ── Stat badges ── */
81	.badgeGrid {
82	  display: grid;
83	  grid-template-columns: repeat(4, auto);
84	  gap: 12px;
85	  justify-content: center;
86	  margin-bottom: 2.5rem;
87	}
88	
89	.statBadge {
90	  display: flex;
91	  align-items: center;
92	  gap: 10px;
93	  background-color: #fff;
94	  border-radius: 10px;
95	  padding: 13px 20px;
96	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
97	}
98	
99	.statIcon {
100	  width: 24px;
101	  height: 24px;
102	  flex-shrink: 0;
103	}
104	
105	.statLabel {
106	  color: #082753;
107	  font-family: 'Roobert PRO', Arial, sans-serif;
108	  font-size: 15px;
109	  font-weight: 500;
110	  line-height: 1.4;
111	  white-space: nowrap;
112	}
113	
114	/* ── CTA row ── */
115	.ctaRow {
116	  display: flex;
117	  justify-content: center;
118	  align-items: center;
119	  gap: 1.25rem;
120	  flex-wrap: wrap;
121	}
122	
123	.ctaPrimary {
124	  display: inline-flex;
125	  align-items: center;
126	  justify-content: center;
127	  color: #fff;
128	  font-family: 'Roobert PRO', Arial, sans-serif;
129	  font-size: 1rem;
130	  font-weight: 700;
131	  line-height: 1.75rem;
132	  text-decoration: none;
133	  background-image: url('/images/webflow/Group-46729-2.svg'),
134	    linear-gradient(90deg, #21cfff, #019ae6);
135	  background-position: 93%, 0 0;
136	  background-repeat: no-repeat, repeat;
137	  background-size: auto, auto;
138	  border-radius: 0.75rem;
139	  padding: 0.75rem 3rem 0.75rem 1.25rem;
140	  border: 2px solid transparent;
141	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
142	  transition: filter 0.15s ease;
143	}
144	
145	.ctaPrimary:hover {
146	  filter: brightness(1.08);
147	}
148	
149	.ctaSecondary {
150	  display: inline-flex;
151	  align-items: center;
152	  justify-content: center;
153	  color: #111827;
154	  font-family: 'Roobert PRO', Arial, sans-serif;
155	  font-size: 1rem;
156	  font-weight: 700;
157	  line-height: 1.75rem;
158	  text-decoration: none;
159	  background-color: rgba(33, 207, 255, 0.13);
160	  background-image: url('/images/webflow/Group-46729-1.svg');
161	  background-position: 94%;
162	  background-repeat: no-repeat;
163	  background-size: auto;
164	  border-radius: 0.75rem;
165	  padding: 0.75rem 3rem 0.75rem 1.25rem;
166	  border: 2px solid transparent;
167	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
168	  transition: background-color 0.15s ease, color 0.15s ease;
169	}
170	
171	.ctaSecondary:hover {
172	  background-color: #092245;
173	  color: #fff;
174	}
175	
176	/* ── 2-column navy content grid ── */
177	.contentGrid {
178	  display: grid;
179	  grid-template-columns: 1fr 1fr;
180	  gap: 0;
181	  background-color: #082753;
182	  border-radius: 20px 20px 0 0;
183	  padding: 56px 48px;
184	  margin-top: 3rem;
185	}
186	
187	.contentCol {
188	  display: flex;
189	  flex-direction: column;
190	  gap: 16px;
191	  padding: 0 24px;
192	}
193	
194	.contentCol:first-child {
195	  border-right: 1px solid rgba(255, 255, 255, 0.1);
196	  padding-left: 0;
197	}
198	
199	.contentCol:last-child {
200	  padding-right: 0;
201	}
202	
203	.contentHeading {
204	  color: #fff;
205	  font-family: 'Roobert PRO', Arial, sans-serif;
206	  font-size: 22px;
207	  font-weight: 700;
208	  line-height: 1.35;
209	  margin: 0;
210	}
211	
212	.contentPara {
213	  color: rgba(255, 255, 255, 0.7);
214	  font-family: 'Roobert PRO', Arial, sans-serif;
215	  font-size: 15px;
216	  font-weight: 400;
217	  line-height: 26px;
218	  margin: 0;
219	}
220	
221	/* ============================================================
222	   min-width: 1280px
223	   ============================================================ */
224	@media screen and (min-width: 1280px) {
225	  .heading {
226	    font-size: 52px;
227	  }
228	}
229	
230	/* ============================================================
231	   max-width: 991px
232	   ============================================================ */
233	@media screen and (max-width: 991px) {
234	  .badgeGrid {
235	    grid-template-columns: repeat(2, auto);
236	  }
237	
238	  .contentGrid {
239	    grid-template-columns: 1fr;
240	    padding: 40px 32px;
241	    gap: 32px;
242	  }
243	
244	  .contentCol:first-child {
245	    border-right: none;
246	    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
247	    padding-left: 0;
248	    padding-bottom: 32px;
249	  }
250	
251	  .contentCol:last-child {
252	    padding-right: 0;
253	  }
254	
255	  .contentCol {
256	    padding: 0;
257	  }
258	}
259	
260	/* ============================================================
261	   max-width: 767px
262	   ============================================================ */
263	@media screen and (max-width: 767px) {
264	  .heading {
265	    font-size: 32px;
266	  }
267	
268	  .contentGrid {
269	    padding: 32px 24px;
270	    border-radius: 16px 16px 0 0;
271	  }
272	}
273	
274	/* ============================================================
275	   max-width: 479px  (mobile)
276	   ============================================================ */
277	@media screen and (max-width: 479px) {
278	  .section {
279	    padding-top: 3rem;
280	    background-image: linear-gradient(180deg, #019ae614 0%, #fff 100%);
281	    background-size: auto;
282	  }
283	
284	  .container {
285	    padding-left: 1rem;
286	    padding-right: 1rem;
287	  }
288	
289	  .heading {
290	    font-size: 1.7rem;
291	    line-height: 1.25;
292	  }
293	
294	  .subtitle {
295	    font-size: 1rem;
296	    padding-left: 0;
297	    padding-right: 0;
298	  }
299	
300	  .badgeGrid {
301	    grid-template-columns: 1fr 1fr;
302	    gap: 10px;
303	    width: 100%;
304	  }
305	
306	  .statBadge {
307	    padding: 10px 14px;
308	  }
309	
310	  .statLabel {
311	    white-space: normal;
312	    font-size: 13px;
313	  }
314	
315	  .ctaRow {
316	    flex-direction: column;
317	    gap: 12px;
318	  }
319	
320	  .ctaPrimary,
321	  .ctaSecondary {
322	    width: 100%;
323	    justify-content: center;
324	    font-size: 1.05rem;
325	    padding-right: 1.25rem;
326	    background-image: none;
327	  }
328	
329	  .ctaPrimary {
330	    background-image: linear-gradient(90deg, #21cfff, #019ae6);
331	  }
332	
333	  .contentGrid {
334	    padding: 28px 20px;
335	    border-radius: 12px 12px 0 0;
336	  }
337	
338	  .contentHeading {
339	    font-size: 19px;
340	  }
341	
342	  .contentPara {
343	    font-size: 14px;
344	    line-height: 24px;
345	  }
346	}
